import{_ as c,I as t,o as r,c as s,b6 as h,j as l,J as i,w as d}from"./chunks/framework.BUXTSoD9.js";const P=JSON.parse('{"title":"Thực hành phát triển hệ thống microservices thương mại điện tử thực phẩm tươi sống","description":"","frontmatter":{},"headers":[],"relativePath":"vi-vn/stage-2/assignments/simple-grocery-microservices/index.md","filePath":"vi-vn/stage-2/assignments/simple-grocery-microservices/index.md"}'),o={name:"vi-vn/stage-2/assignments/simple-grocery-microservices/index.md"},u={style:{margin:"32px 0"}};function g(p,n,m,k,b,v){const a=t("StepBar"),e=t("ClientOnly");return r(),s("div",null,[n[0]||(n[0]=h('<h1 id="thuc-hanh-phat-trien-he-thong-microservices-thuong-mai-đien-tu-thuc-pham-tuoi-song" tabindex="-1">Thực hành phát triển hệ thống microservices thương mại điện tử thực phẩm tươi sống <a class="header-anchor" href="#thuc-hanh-phat-trien-he-thong-microservices-thuong-mai-đien-tu-thuc-pham-tuoi-song" aria-label="Permalink to “Thực hành phát triển hệ thống microservices thương mại điện tử thực phẩm tươi sống”">​</a></h1><h2 id="tong-quan" tabindex="-1">Tổng quan <a class="header-anchor" href="#tong-quan" aria-label="Permalink to “Tổng quan”">​</a></h2><p>Dự án thực chiến này yêu cầu bạn hoàn thành một hệ thống microservices thương mại điện tử thực phẩm tươi sống dựa trên một PRD thực tế, xây dựng từ đầu. Khác với các dự án dịch vụ đơn lẻ trước đó, backend của dự án này được chia thành nhiều dịch vụ độc lập theo nghiệp vụ, thông qua API Gateway thống nhất对外. Bạn sẽ học cách thiết kế ranh giới dịch vụ, cách xử lý vấn đề nhất quán dữ liệu cross-service.</p><p>Đây là phần thực hành tổng hợp của Stage 2. Kiến trúc microservices rất phổ biến trong thực tế công việc, sau khi nắm vững tư duy cơ bản về phân tách dịch vụ và định tuyến gateway, bạn có thể ứng phó với thiết kế hệ thống backend phức tạp hơn.</p><h2 id="kien-thuc-tien-quyet" tabindex="-1">Kiến thức tiên quyết <a class="header-anchor" href="#kien-thuc-tien-quyet" aria-label="Permalink to “Kiến thức tiên quyết”">​</a></h2><p>Trước khi bắt đầu dự án này, bạn nên đã nắm được các nội dung sau:</p><ul><li>Thiết kế trang frontend và sử dụng thư viện component (<a href="./../../frontend/ui-design/">Thiết kế UI</a>, <a href="./../../frontend/modern-component-library/">Thư viện component hiện đại</a>)</li><li>Thiết kế và phát triển API backend (<a href="./../../backend/ai-interface-code/">Viết code API</a>)</li><li>Cơ sở dữ liệu cơ bản và Supabase (<a href="./../../backend/database-supabase/">Từ cơ sở dữ liệu đến Supabase</a>)</li><li>Quy trình làm việc Git và triển khai (<a href="./../../backend/git-workflow/">Git và GitHub</a>, <a href="./../../backend/zeabur-deployment/">Triển khai ứng dụng Web</a>)</li></ul><h2 id="muc-tieu-hoc-tap" tabindex="-1">Mục tiêu học tập <a class="header-anchor" href="#muc-tieu-hoc-tap" aria-label="Permalink to “Mục tiêu học tập”">​</a></h2><p>Sau khi hoàn thành bài thực hành này, bạn sẽ có thể:</p><ol><li>Đọc PRD và trích xuất danh sách công việc phát triển hệ thống microservices</li><li>Phân tách ranh giới dịch vụ theo lĩnh vực nghiệp vụ (xác thực, sản phẩm, tồn kho, đơn hàng)</li><li>Thiết kế và triển khai định tuyến API Gateway</li><li>Xử lý các vấn đề cross-service như trừ tồn kho và nhất quán đơn hàng</li><li>Hoàn thành liên hợp đầu cuối, bàn giao nguyên mẫu microservices có thể demo</li></ol><h2 id="gioi-thieu-du-an" tabindex="-1">Giới thiệu dự án <a class="header-anchor" href="#gioi-thieu-du-an" aria-label="Permalink to “Giới thiệu dự án”">​</a></h2><p>Sản phẩm bạn cần xây dựng là một hệ thống microservices thương mại điện tử thực phẩm tươi sống:</p><table tabindex="0"><thead><tr><th>Hệ thống con</th><th>Trách nhiệm</th></tr></thead><tbody><tr><td><strong>Trang người dùng</strong></td><td>Duyệt sản phẩm, đặt hàng, xem đơn hàng</td></tr><tr><td><strong>Trang quản trị</strong></td><td>Quản lý sản phẩm, quản lý tồn kho, quản lý đơn hàng</td></tr></tbody></table><p>Backend được phân tách theo nghiệp vụ thành các dịch vụ sau:</p><table tabindex="0"><thead><tr><th>Dịch vụ</th><th>Trách nhiệm</th></tr></thead><tbody><tr><td><strong>API Gateway</strong></td><td>Điểm vào thống nhất, chuyển tiếp định tuyến, kiểm tra xác thực</td></tr><tr><td><strong>Auth Service</strong></td><td>Đăng ký người dùng, đăng nhập, cấp JWT</td></tr><tr><td><strong>Catalog Service</strong></td><td>Quản lý thông tin sản phẩm</td></tr><tr><td><strong>Inventory Service</strong></td><td>Quản lý số lượng tồn kho</td></tr><tr><td><strong>Order Service</strong></td><td>Tạo đơn hàng, quản lý trạng thái</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Đường dẫn PRD</p><p>Tài liệu yêu cầu của dự án này nằm trên GitHub: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-cn/stage-2/assignments/simple-grocery-microservices/PRD.md" target="_blank" rel="noreferrer">Xem PRD</a></p></div>',16)),l("div",u,[i(e,null,{default:d(()=>[i(a,{active:0,items:[{title:"Phân tích yêu cầu",description:"Đọc PRD, xác định phân tách dịch vụ, trang và chuỗi giao dịch"},{title:"Xây dựng khung",description:"Tạo khung frontend, gateway và các dịch vụ"},{title:"Phát triển lặp",description:"Bổ sung API từng module, sửa nhất quán tồn kho và đơn hàng"},{title:"Liên hợp & triển khai",description:"Chạy đầu cuối, triển khai và chuẩn bị demo"}]})]),_:1})]),n[1]||(n[1]=h(`<h2 id="phan-1-phan-tich-yeu-cau" tabindex="-1">Phần 1: Phân tích yêu cầu <a class="header-anchor" href="#phan-1-phan-tich-yeu-cau" aria-label="Permalink to “Phần 1: Phân tích yêu cầu”">​</a></h2><h3 id="_1-1-đoc-prd" tabindex="-1">1.1 Đọc PRD <a class="header-anchor" href="#_1-1-đoc-prd" aria-label="Permalink to “1.1 Đọc PRD”">​</a></h3><p>Mở tài liệu PRD, tập trung trả lời các câu hỏi sau:</p><ul><li>Dịch vụ được phân tách như thế nào? Ranh giới trách nhiệm của mỗi dịch vụ là gì?</li><li>Frontend và trang quản trị lần lượt có những trang nào?</li><li>Chiến lược trừ tồn kho sau khi đặt hàng là gì? Xử lý thành công / thất bại / timeout mỗi loại như thế nào?</li><li>Phiên bản đầu tiên những khả năng phức tạp nào (như giao dịch phân tán, hàng đợi tin nhắn) tạm thời không làm?</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Nếu các câu hỏi trên chưa có câu trả lời rõ ràng, đừng bắt đầu viết code. Hiểu sai yêu cầu là nguyên nhân phổ biến nhất dẫn đến phải làm lại.</p></div><h3 id="_1-2-xac-nhan-kien-truc-he-thong" tabindex="-1">1.2 Xác nhận kiến trúc hệ thống <a class="header-anchor" href="#_1-2-xac-nhan-kien-truc-he-thong" aria-label="Permalink to “1.2 Xác nhận kiến trúc hệ thống”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; fe[&quot;Trang frontend&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  fe --&gt; gw[&quot;API Gateway&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; auth[&quot;Auth Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; catalog[&quot;Catalog Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; inventory[&quot;Inventory Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; order[&quot;Order Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  order --&gt; inventory</span></span></code></pre></div><h2 id="phan-2-xay-dung-khung-du-an" tabindex="-1">Phần 2: Xây dựng khung dự án <a class="header-anchor" href="#phan-2-xay-dung-khung-du-an" aria-label="Permalink to “Phần 2: Xây dựng khung dự án”">​</a></h2><h3 id="_2-1-tao-cau-truc-du-an" tabindex="-1">2.1 Tạo cấu trúc dự án <a class="header-anchor" href="#_2-1-tao-cau-truc-du-an" aria-label="Permalink to “2.1 Tạo cấu trúc dự án”">​</a></h3><p>Tham khảo prompt:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Vui lòng dựa trên PRD hiện tại, giúp tôi tạo cấu trúc dự án của hệ thống microservices thương mại điện tử thực phẩm tươi sống.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Yêu cầu:</span></span>
<span class="line"><span>1. Tạo khung frontend trang người dùng và trang quản trị</span></span>
<span class="line"><span>2. Tạo năm thư mục: api-gateway, auth-service, catalog-service, inventory-service, order-service</span></span>
<span class="line"><span>3. Mỗi dịch vụ trước tiên chỉ làm điểm vào có thể chạy tối thiểu</span></span>
<span class="line"><span>4. Trước tiên không kết nối cơ sở dữ liệu thực tế và thanh toán</span></span></code></pre></div><h3 id="_2-2-xac-minh-cau-truc-du-an" tabindex="-1">2.2 Xác minh cấu trúc dự án <a class="header-anchor" href="#_2-2-xac-minh-cau-truc-du-an" aria-label="Permalink to “2.2 Xác minh cấu trúc dự án”">​</a></h3><p>Kiểm tra từng mục:</p><ul><li>[ ] Cấu trúc thư mục của năm dịch vụ rõ ràng</li><li>[ ] API Gateway có thể khởi động và chuyển tiếp yêu cầu</li><li>[ ] API kiểm tra sức khỏe của mỗi dịch vụ có thể sử dụng</li><li>[ ] Trang frontend trang người dùng và trang quản trị có thể truy cập</li></ul><h2 id="phan-3-phat-trien-lap" tabindex="-1">Phần 3: Phát triển lặp <a class="header-anchor" href="#phan-3-phat-trien-lap" aria-label="Permalink to “Phần 3: Phát triển lặp”">​</a></h2><h3 id="_3-1-trien-khai-theo-module" tabindex="-1">3.1 Triển khai theo module <a class="header-anchor" href="#_3-1-trien-khai-theo-module" aria-label="Permalink to “3.1 Triển khai theo module”">​</a></h3><ol><li><strong>API Gateway</strong>: Cấu hình định tuyến, middleware kiểm tra JWT</li><li><strong>Auth Service</strong>: Đăng ký, đăng nhập, cấp JWT</li><li><strong>Catalog Service</strong>: CRUD sản phẩm, truy vấn danh sách</li><li><strong>Inventory Service</strong>: Truy vấn tồn kho, trừ tồn kho</li><li><strong>Order Service</strong>: Tạo đơn hàng, chuyển trạng thái, liên kết tồn kho</li><li><strong>Trang quản trị</strong>: Quản lý sản phẩm, quản lý tồn kho, quản lý đơn hàng</li></ol><h3 id="_3-2-tu-kiem-tra-module" tabindex="-1">3.2 Tự kiểm tra module <a class="header-anchor" href="#_3-2-tu-kiem-tra-module" aria-label="Permalink to “3.2 Tự kiểm tra module”">​</a></h3><table tabindex="0"><thead><tr><th>Mục kiểm tra</th><th>Phương pháp xác minh</th></tr></thead><tbody><tr><td>Định tuyến gateway</td><td>API của mỗi dịch vụ có được chuyển tiếp chính xác qua gateway không</td></tr><tr><td>Cách ly phân quyền</td><td>API trang người dùng và trang quản trị có cách ly không</td></tr><tr><td>Nhất quán dữ liệu</td><td>Dữ liệu sản phẩm và tồn kho có đồng bộ không</td></tr><tr><td>Chuỗi giao dịch</td><td>Sau khi đặt hàng, trừ tồn kho, trạng thái đơn hàng có nhất quán không</td></tr><tr><td>Xử lý thất bại</td><td>Khi tồn kho không đủ hoặc timeout có cơ chế bù đắp không</td></tr></tbody></table><h2 id="phan-4-lien-hop-va-trien-khai" tabindex="-1">Phần 4: Liên hợp và Triển khai <a class="header-anchor" href="#phan-4-lien-hop-va-trien-khai" aria-label="Permalink to “Phần 4: Liên hợp và Triển khai”">​</a></h2><h3 id="_4-1-kiem-thu-đau-cuoi" tabindex="-1">4.1 Kiểm thử đầu cuối <a class="header-anchor" href="#_4-1-kiem-thu-đau-cuoi" aria-label="Permalink to “4.1 Kiểm thử đầu cuối”">​</a></h3><p>Ít nhất xác minh các kịch bản sau:</p><ul><li>Duyệt sản phẩm → Thêm vào giỏ hàng → Đặt hàng → Xem đơn hàng</li><li>Quản trị viên → Thêm sản phẩm → Cập nhật tồn kho → Xem đơn hàng</li></ul><h2 id="san-pham-ban-giao" tabindex="-1">Sản phẩm bàn giao <a class="header-anchor" href="#san-pham-ban-giao" aria-label="Permalink to “Sản phẩm bàn giao”">​</a></h2><p>Sau khi hoàn thành dự án này, bạn cần nộp các nội dung sau:</p><ul><li>[ ] Liên kết demo trực tuyến có thể truy cập</li><li>[ ] Liên kết kho mã nguồn (bao gồm README)</li><li>[ ] Tài liệu PRD</li><li>[ ] Ảnh chụp màn hình các trang cốt lõi (danh sách sản phẩm, trang đặt hàng, trang đơn hàng, back-office quản trị)</li><li>[ ] Video demo 60 giây</li></ul><h2 id="tieu-chi-cham-điem" tabindex="-1">Tiêu chí chấm điểm <a class="header-anchor" href="#tieu-chi-cham-điem" aria-label="Permalink to “Tiêu chí chấm điểm”">​</a></h2><table tabindex="0"><thead><tr><th>Chiều</th><th>Yêu cầu cơ bản</th><th>Yêu cầu nâng cao</th></tr></thead><tbody><tr><td>Căn chỉnh PRD</td><td>Trang, chức năng, phân tách dịch vụ cơ bản khớp với PRD</td><td>Có thể giải thích rõ ràng lý do phân tách dịch vụ</td></tr><tr><td>Chuỗi sản phẩm</td><td>Duyệt → Đặt hàng → Trừ tồn kho → Xem đơn hàng có thể chạy qua</td><td>Timeout đơn hàng hoặc tồn kho không đủ có cơ chế bù đắp</td></tr><tr><td>Kiến trúc dịch vụ</td><td>Mỗi dịch vụ có thể khởi động độc lập, truy cập thống nhất qua gateway</td><td>Giao tiếp giữa dịch vụ có xử lý lỗi và thử lại</td></tr><tr><td>Khả năng back-office</td><td>Quản lý sản phẩm, tồn kho, đơn hàng có thể thao tác</td><td>Trang quản trị có thống kê dữ liệu</td></tr><tr><td>Độ hoàn thiện kỹ thuật</td><td>Frontend, gateway, dịch vụ, chuỗi cơ sở dữ liệu đã kết nối</td><td>Có Docker Compose hoặc điều phối tương tự</td></tr></tbody></table><h2 id="tai-lieu-tham-khao" tabindex="-1">Tài liệu tham khảo <a class="header-anchor" href="#tai-lieu-tham-khao" aria-label="Permalink to “Tài liệu tham khảo”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">Thiết kế UI</a></li><li><a href="./../../frontend/modern-component-library/">Sử dụng thư viện component hiện đại để cập nhật giao diện</a></li><li><a href="./../../backend/database-supabase/">Từ cơ sở dữ liệu đến Supabase</a></li><li><a href="./../../backend/ai-interface-code/">Mô hình hỗ trợ viết code API và tài liệu API bằng mô hình lớn</a></li><li><a href="./../../backend/git-workflow/">Quy trình làm việc Git và GitHub</a></li><li><a href="./../../backend/zeabur-deployment/">Cách triển khai ứng dụng Web</a></li></ul>`,30))])}const f=c(o,[["render",g]]);export{P as __pageData,f as default};
